def clip_window(left, right, point):
    if left > right:
        raise ValueError("reversed window")
    return left <= point < right

def release_key(label):
    parts = label.removeprefix("v").split(".")
    if len(parts) != 3:
        raise ValueError("expected three release fields")
    return tuple(int(part) for part in parts)

def require_text(value):
    if not isinstance(value, str):
        raise TypeError("expected text")
    return value

def clean_tag(tag):
    return "-".join(require_text(tag).split()).lower()

def cache_name(value):
    key = value.strip()
    if not key:
        raise ValueError("empty cache name")
    return key
